/* WARNING: 本项目专属“粘人精”，严禁出现 Kiro、Krio、周棋洛等任何相关英文或拼音命名！ */
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { worldBooks, worldBookGroups } from '../../../store'
import type { ForumAccountKind, ForumAvatarLibraryItem, ForumBridgeMode, ForumMemoryType, ForumParticipantPolicy, ForumSnapshot } from '../../../types/forum'
import ForumHeader from '../components/ForumHeader.vue'
import ForumAvatar from '../components/ForumAvatar.vue'
import AvatarUploadModal from '../../AvatarUploadModal.vue'
import { IMAGE_PROVIDERS } from '../../../services/imageProviderRegistry'

const props=defineProps<{snapshot:ForumSnapshot;activeAccountId:string;participantCandidates:()=>any[]} >()
const emit=defineEmits<{
  (e:'back'):void;(e:'switch-account',id:string):void;(e:'add-account',value:{name:string;handle:string;kind:ForumAccountKind;privacy:'public'|'normal'|'private';bio:string}):void
  (e:'update-profile',value:{name:string;handle:string;avatar:string;bio:string;location:string}):void
  (e:'participation',entry:any,enabled:boolean):void;(e:'participant-policy',subjectId:string,patch:Partial<ForumParticipantPolicy>):void;(e:'bridge',subjectId:string,direction:'forumToChat'|'chatToForum',mode:ForumBridgeMode):void
  (e:'bridge-types',subjectId:string,direction:'forumToChat'|'chatToForum',types:ForumMemoryType[]):void
  (e:'bind-world',circleId:string,bookIds:string[],groupIds:string[]):void
  (e:'add-avatar-files',files:File[],group:ForumAvatarLibraryItem['group']):void
  (e:'add-avatar-url',url:string,group:ForumAvatarLibraryItem['group']):void
  (e:'generate-avatar',prompt:string,group:ForumAvatarLibraryItem['group']):void
  (e:'remove-avatar',id:string,deleteMedia?:boolean):void
}>()
type Section='accounts'|'characters'|'circles'|'privacy'|'bridge'|'ai'|'dm'|'avatars'|'media'
const section=ref<Section>('accounts');const candidates=ref<any[]>([]);const addingAccount=ref(false);const name=ref('');const handle=ref('');const kind=ref<ForumAccountKind>('alternate');const privacy=ref<'public'|'normal'|'private'>('normal');const bio=ref('');const expandedSubject=ref('')
const profileName=ref('');const profileHandle=ref('');const profileAvatar=ref('');const profileBio=ref('');const profileLocation=ref('');const avatarUploadVisible=ref(false);const profileMessage=ref('')
onMounted(()=>{candidates.value=props.participantCandidates()})
const activeAccount=computed(()=>props.snapshot.accounts.find(item=>item.id===props.activeAccountId))
watch(activeAccount,account=>{profileName.value=account?.name||'';profileHandle.value=account?.handle||'';profileAvatar.value=account?.avatar||'';profileBio.value=account?.bio||'';profileLocation.value=account?.location||'';profileMessage.value=''},{immediate:true})
const profileHandleTaken=computed(()=>props.snapshot.accounts.some(item=>item.id!==props.activeAccountId&&item.handle.toLowerCase()===profileHandle.value.trim().replace(/^@/,'').replace(/\s+/g,'_').toLowerCase()))
const canSaveProfile=computed(()=>Boolean(profileName.value.trim()&&profileHandle.value.trim()&&!profileHandleTaken.value))
const submitProfile=()=>{if(!canSaveProfile.value)return;emit('update-profile',{name:profileName.value,handle:profileHandle.value,avatar:profileAvatar.value,bio:profileBio.value,location:profileLocation.value});profileMessage.value='个人资料已保存'}
const characterSubjects=computed(()=>props.snapshot.subjects.filter(item=>item.kind==='character'))
const policyFor=(id:string)=>props.snapshot.participantPolicies.find(item=>item.subjectId===id)
const bridgeFor=(id:string)=>props.snapshot.bridgePolicies.find(item=>item.subjectId===id)
const accountCount=(id:string)=>props.snapshot.accounts.filter(item=>item.subjectId===id).length
const submitAccount=()=>{if(!name.value.trim()||!handle.value.trim())return;emit('add-account',{name:name.value,handle:handle.value,kind:kind.value,privacy:privacy.value,bio:bio.value});name.value='';handle.value='';bio.value='';addingAccount.value=false}
const toggleCircle=(subjectId:string,circleId:string,checked:boolean)=>{const current=policyFor(subjectId)?.allowedCircleIds||[];emit('participant-policy',subjectId,{allowedCircleIds:checked?[...new Set([...current,circleId])]:current.filter(id=>id!==circleId)})}
const selectedBookIds=(circleId:string)=>{const circle=props.snapshot.circles.find(item=>item.id===circleId);return props.snapshot.worldBindings.find(item=>item.id===circle?.worldBindingId)?.bookIds||[]}
const toggleBook=(circleId:string,bookId:string,checked:boolean)=>{const ids=selectedBookIds(circleId);emit('bind-world',circleId,checked?[...new Set([...ids,bookId])]:ids.filter(id=>id!==bookId),[])}
const toggleCircleSubject=(circleId:string,subjectId:string,checked:boolean)=>{const circle=props.snapshot.circles.find(item=>item.id===circleId);if(!circle)return;circle.participantSubjectIds=checked?[...new Set([...circle.participantSubjectIds,subjectId])]:circle.participantSubjectIds.filter(id=>id!==subjectId)}
const modeLabel=(mode?:ForumBridgeMode)=>({off:'关闭',all:'完全开启',selected:'选择性',summary:'仅摘要',important:'仅重要', 'reachable-only':'合理得知'}[mode||'off'])
const memoryTypeOptions:Array<{id:ForumMemoryType;label:string}>=[{id:'identity',label:'身份'},{id:'public-profile',label:'公开资料'},{id:'relationship',label:'关系'},{id:'post',label:'发帖'},{id:'comment',label:'评论'},{id:'like',label:'点赞'},{id:'follow',label:'关注'},{id:'dm',label:'私信'},{id:'group',label:'群聊'},{id:'circle',label:'圈子'},{id:'important-event',label:'重要事件'},{id:'user-public',label:'公开发言'},{id:'user-private',label:'私密发言'},{id:'chat-daily',label:'聊天日常'},{id:'chat-secret',label:'聊天秘密'},{id:'emotion',label:'感情变化'},{id:'image',label:'图片'},{id:'voice',label:'语音'},{id:'offline-event',label:'线下事件'}]
const autoImageProviders=IMAGE_PROVIDERS.filter(item=>item.capabilities.textToImage)
const avatarGroup=ref<ForumAvatarLibraryItem['group']>('other');const avatarUrl=ref('');const avatarPrompt=ref('');const avatarFiles=ref<HTMLInputElement|null>(null)
const submitAvatarUrl=()=>{if(!avatarUrl.value.trim())return;emit('add-avatar-url',avatarUrl.value,avatarGroup.value);avatarUrl.value=''}
const submitAvatarFiles=(event:Event)=>{const files=[...((event.target as HTMLInputElement).files||[])];if(files.length)emit('add-avatar-files',files,avatarGroup.value);(event.target as HTMLInputElement).value=''}
const autoImageProviderLabel=(id:string,name:string)=>id==='pollinations'?`${name}（默认 / 低门槛）`:id==='aihorde'?`${name}（社区免费）`:name
const toggleBridgeType=(subjectId:string,direction:'forumToChat'|'chatToForum',type:ForumMemoryType,checked:boolean)=>{const current=bridgeFor(subjectId)?.[direction].memoryTypes||[];emit('bridge-types',subjectId,direction,checked?[...new Set([...current,type])]:current.filter(item=>item!==type))}
</script>

<template>
  <div class="settings-view"><ForumHeader title="论坛设置" show-back @back="emit('back')"/>
    <nav class="settings-tabs"><button v-for="item in [{id:'accounts',t:'账号'},{id:'characters',t:'角色'},{id:'circles',t:'圈子'},{id:'privacy',t:'隐私'},{id:'bridge',t:'互通'},{id:'ai',t:'AI'},{id:'dm',t:'私信'},{id:'avatars',t:'头像库'},{id:'media',t:'媒体'}]" :key="item.id" :class="{active:section===item.id}" @click="section=item.id as Section">{{item.t}}</button></nav>
    <div class="settings-scroll">
      <template v-if="section==='accounts'">
        <div class="section-head"><div><b>个人资料</b><small>修改当前论坛账号对外显示的信息</small></div></div>
        <form class="profile-form" @submit.prevent="submitProfile">
          <button class="profile-avatar-button" type="button" @click="avatarUploadVisible=true"><ForumAvatar :src="profileAvatar" :name="profileName||'我'" size="xl"/><span>{{profileAvatar?'更换头像':'添加头像'}}</span></button>
          <div class="profile-fields">
            <label><span>昵称</span><input v-model="profileName" maxlength="24" placeholder="论坛中显示的名字"/></label>
            <label><span>论坛号</span><div class="profile-handle-input"><i>@</i><input v-model="profileHandle" maxlength="32" placeholder="唯一 ID"/></div></label>
            <small v-if="profileHandleTaken" class="field-error">这个论坛号已被使用</small>
            <label><span>简介</span><textarea v-model="profileBio" maxlength="160" placeholder="介绍一下自己"></textarea></label>
            <label><span>所在地</span><input v-model="profileLocation" maxlength="40" placeholder="选填"/></label>
            <div class="profile-save-row"><span>{{profileMessage}}</span><button type="submit" :disabled="!canSaveProfile">保存资料</button></div>
          </div>
        </form>
        <div class="section-head"><div><b>论坛账号</b><small>切换后关注、私信、圈子与推荐均独立</small></div><button @click="addingAccount=!addingAccount">{{addingAccount?'取消':'新建'}}</button></div>
        <form v-if="addingAccount" class="inline-form" @submit.prevent="submitAccount"><input v-model="name" maxlength="24" placeholder="昵称"/><input v-model="handle" maxlength="32" placeholder="论坛号"/><div class="form-split"><select v-model="kind"><option value="alternate">小号</option><option value="private">私密号</option><option value="circle">圈子号</option><option value="work">工作号</option><option value="custom">自定义</option></select><select v-model="privacy"><option value="public">公开</option><option value="normal">普通</option><option value="private">私密</option></select></div><input v-model="bio" maxlength="160" placeholder="简介（可选）"/><button class="form-submit" :disabled="!name.trim()||!handle.trim()">创建账号</button></form>
        <button v-for="account in snapshot.accounts.filter(a=>snapshot.subjects.find(s=>s.id===a.subjectId)?.kind==='user'&&!a.isArchived)" :key="account.id" class="setting-row account-row" @click="emit('switch-account',account.id)"><ForumAvatar :src="account.avatar" :name="account.name" size="md"/><span><b>{{account.name}}<em>{{account.kind==='main'?'大号':account.kind==='alternate'?'小号':account.kind==='private'?'私密号':account.kind}}</em></b><small>@{{account.handle}} · {{account.privacy}}</small></span><i>{{account.id===activeAccountId?'当前':'切换'}}</i></button>
        <p class="plain-note">论坛账号和聊天账号不等同；这里的账号真实归属不会自动公开给其他角色或 NPC。</p>
      </template>

      <template v-else-if="section==='characters'">
        <div class="section-head"><div><b>角色参与论坛</b><small>关闭时，该角色对论坛完全不存在</small></div></div>
        <div v-if="!candidates.length" class="empty-compact">聊天中还没有可导入的角色</div>
        <div v-for="entry in candidates" :key="entry.entityId" class="participant-item">
          <button class="setting-row" @click="expandedSubject=expandedSubject===(entry.subject?.id||entry.entityId)?'':(entry.subject?.id||entry.entityId)"><span class="letter-avatar">{{(entry.socialProfile?.nickname||entry.name||'?').slice(0,1)}}</span><span><b>{{entry.socialProfile?.nickname||entry.name}}</b><small>{{entry.enabled?`已参与 · ${accountCount(entry.subject?.id)} 个账号`:'未参与论坛'}}</small></span><i>›</i></button>
          <div v-if="expandedSubject===(entry.subject?.id||entry.entityId)" class="participant-editor">
            <label class="switch-row"><span><b>参与论坛</b><small>最高优先级准入开关</small></span><input :checked="entry.enabled" type="checkbox" @change="emit('participation',entry,($event.target as HTMLInputElement).checked);entry.enabled=($event.target as HTMLInputElement).checked"/><i></i></label>
            <template v-if="entry.enabled&&entry.subject">
              <div class="mini-title">允许出现的圈子</div><label v-for="circle in snapshot.circles" :key="circle.id" class="check-row"><span>{{circle.name}}</span><input type="checkbox" :checked="policyFor(entry.subject.id)?.allowedCircleIds.includes(circle.id)" @change="toggleCircle(entry.subject.id,circle.id,($event.target as HTMLInputElement).checked)"/></label>
              <div class="mini-title">可见与联系</div><label v-for="item in [{k:'allowSearch',t:'允许搜索'},{k:'allowRecommendation',t:'允许推荐'},{k:'allowMention',t:'允许提及'},{k:'allowDm',t:'允许私信'},{k:'allowGroup',t:'允许群聊'}]" :key="item.k" class="switch-row compact"><span>{{item.t}}</span><input type="checkbox" :checked="(policyFor(entry.subject.id) as any)?.[item.k]" @change="emit('participant-policy',entry.subject.id,{[item.k]:($event.target as HTMLInputElement).checked})"/><i></i></label>
            </template>
          </div>
        </div>
      </template>

      <template v-else-if="section==='circles'">
        <div class="section-head"><div><b>圈子背景与权限</b><small>世界书只提供背景，不参与角色准入</small></div></div>
        <details v-for="circle in snapshot.circles" :key="circle.id" class="setting-details">
          <summary><span class="letter-avatar">{{circle.avatar}}</span><span><b>{{circle.name}}</b><small>{{circle.joinMode}} · 按生成批次更新</small></span><i>›</i></summary>
          <div class="details-body">
            <div class="mini-title">这里聊什么</div><textarea v-model="circle.contentScope" class="circle-scope-input" maxlength="800" placeholder="明确圈内内容范围，也可写不适合出现的内容"></textarea>
            <div class="mini-title">对外简介</div><input v-model="circle.description" class="circle-description-input" maxlength="80" placeholder="列表中显示的简短介绍"/>
            <div class="mini-title">绑定世界书</div><label v-for="book in worldBooks.filter(b=>b.type==='book')" :key="book.id" class="check-row"><span>{{book.title}}</span><input type="checkbox" :checked="selectedBookIds(circle.id).includes(book.id)" @change="toggleBook(circle.id,book.id,($event.target as HTMLInputElement).checked)"/></label><p v-if="!worldBooks.length" class="plain-note">暂无世界书</p><div v-if="worldBookGroups.length" class="mini-note">支持 {{worldBookGroups.length}} 个世界书分组；条目权重沿用世界书设置。</div>
            <div class="mini-title">圈子角色白名单</div><label v-for="subject in characterSubjects.filter(s=>policyFor(s.id)?.enabled)" :key="subject.id" class="check-row"><span>{{subject.displayName}}</span><input type="checkbox" :checked="circle.participantSubjectIds.includes(subject.id)" @change="toggleCircleSubject(circle.id,subject.id,($event.target as HTMLInputElement).checked)"/></label><p v-if="!characterSubjects.some(s=>policyFor(s.id)?.enabled)" class="mini-note">暂无已参与论坛的角色。白名单为空时只按角色自身参与范围过滤。</p>
            <div class="mini-title">内容规则</div><div class="tag-line"><span>匿名 {{circle.anonymousMode}}</span><span>投票 {{circle.allowPoll?'允许':'关闭'}}</span><span>抽奖 {{circle.allowLottery?'允许':'关闭'}}</span></div>
          </div>
        </details>
      </template>

      <template v-else-if="section==='privacy'">
        <div class="section-head"><div><b>关系与可见性</b><small>拉黑、屏蔽、静音和“不让 TA 看”彼此独立</small></div></div>
        <div class="stat-grid"><div><b>{{snapshot.blocks.filter(i=>i.ownerAccountId===activeAccountId).length}}</b><span>拉黑</span></div><div><b>{{snapshot.mutes.filter(i=>i.ownerAccountId===activeAccountId).length}}</b><span>屏蔽/静音</span></div><div><b>{{snapshot.visibilityRules.filter(i=>i.ownerAccountId===activeAccountId).length}}</b><span>可见限制</span></div></div>
        <div class="setting-row static"><span><b>拉黑</b><small>阻断主页、搜索、关注、私信和互动</small></span></div><div class="setting-row static"><span><b>屏蔽</b><small>只过滤自己看到的人、圈子、话题或关键词</small></span></div><div class="setting-row static"><span><b>静音</b><small>保留关注关系，可设置失效时间</small></span></div><div class="setting-row static"><span><b>不让 TA 看</b><small>按帖子、圈子、媒体和状态控制对方视野</small></span></div>
        <p class="plain-note">具体对象的操作入口位于对方主页；对方通常不会收到屏蔽或静音提示。</p>
      </template>

      <template v-else-if="section==='bridge'">
        <div class="section-head"><div><b>聊天记忆互通</b><small>逐角色、逐方向隔离；默认只带入合理得知内容</small></div></div>
        <div v-for="subject in characterSubjects" :key="subject.id" class="bridge-card">
          <b>{{subject.displayName}}</b>
          <label><span>论坛 → 聊天</span><select :value="bridgeFor(subject.id)?.forumToChat.mode||'off'" @change="emit('bridge',subject.id,'forumToChat',($event.target as HTMLSelectElement).value as ForumBridgeMode)"><option v-for="m in ['off','all','selected','summary','important','reachable-only']" :key="m" :value="m">{{modeLabel(m as ForumBridgeMode)}}</option></select></label>
          <div v-if="bridgeFor(subject.id)?.forumToChat.mode==='selected'" class="memory-type-grid"><label v-for="item in memoryTypeOptions" :key="`out-${item.id}`"><input type="checkbox" :checked="bridgeFor(subject.id)?.forumToChat.memoryTypes.includes(item.id)" @change="toggleBridgeType(subject.id,'forumToChat',item.id,($event.target as HTMLInputElement).checked)"><span>{{item.label}}</span></label></div>
          <label><span>聊天 → 论坛</span><select :value="bridgeFor(subject.id)?.chatToForum.mode||'off'" @change="emit('bridge',subject.id,'chatToForum',($event.target as HTMLSelectElement).value as ForumBridgeMode)"><option v-for="m in ['off','all','selected','summary','important','reachable-only']" :key="m" :value="m">{{modeLabel(m as ForumBridgeMode)}}</option></select></label>
          <div v-if="bridgeFor(subject.id)?.chatToForum.mode==='selected'" class="memory-type-grid"><label v-for="item in memoryTypeOptions" :key="`in-${item.id}`"><input type="checkbox" :checked="bridgeFor(subject.id)?.chatToForum.memoryTypes.includes(item.id)" @change="toggleBridgeType(subject.id,'chatToForum',item.id,($event.target as HTMLInputElement).checked)"><span>{{item.label}}</span></label></div>
          <small v-if="!policyFor(subject.id)?.enabled">该角色未参与论坛，聊天信息仍不会进入论坛。</small>
        </div>
        <div v-if="!characterSubjects.length" class="empty-compact">开启角色参与后可配置记忆桥接</div>
      </template>

      <template v-else-if="section==='ai'">
        <div class="section-head"><div><b>内容生成</b><small>论坛只响应你明确点击的生成操作</small></div></div>
        <div class="setting-row static"><span><b>手动调用</b><small>打开页面、浏览、点赞和等待都不会调用 API</small></span><i>固定</i></div>
        <div class="setting-row static"><span><b>回复时间</b><small>默认立即回复；可在评论或私信中手动开启在线状态</small></span><i>即时</i></div>
        <div class="setting-row static"><span><b>轻量陌生人</b><small>关注和私信只保留论坛身份，同意好友申请后才进入聊天 App</small></span></div>
        <p class="plain-note">刷新帖子、增量或覆盖评论、生成指定回复和查看好友动向都有独立按钮；每次点击只执行当前这一次请求。</p>
      </template>

      <template v-else-if="section==='dm'">
        <div class="section-head"><div><b>论坛私信生成</b><small>每次只使用当前对话；最终消息同一请求生成，延时仅控制本地显示</small></div></div>
        <label class="setting-row"><span><b>默认回复时机</b><small>在线状态会让模型返回建议分钟数</small></span><select v-model="snapshot.settings.dm.replyTiming" class="row-select"><option value="immediate">立即</option><option value="presence-aware">在线状态</option><option value="fixed">固定延时</option><option value="range">随机区间</option></select></label>
        <label v-if="snapshot.settings.dm.replyTiming==='fixed'" class="range-row"><span><b>固定分钟</b><em>{{snapshot.settings.dm.fixedDelayMinutes}}</em></span><input v-model.number="snapshot.settings.dm.fixedDelayMinutes" type="range" min="0" max="1440"></label>
        <div v-if="snapshot.settings.dm.replyTiming==='range'" class="runtime-switch"><label class="compact-select-row"><span>最短分钟</span><input v-model.number="snapshot.settings.dm.rangeDelayMin" type="number" min="0"></label><label class="compact-select-row"><span>最长分钟</span><input v-model.number="snapshot.settings.dm.rangeDelayMax" type="number" min="0"></label></div>
        <label class="setting-row"><span><b>并发方式</b><small>同一会话可排队；不同会话不互相污染</small></span><select v-model="snapshot.settings.dm.concurrency" class="row-select"><option value="queue">逐会话排队</option><option value="parallel">允许并行</option></select></label>
        <label class="setting-row"><span><b>待显示消息</b><small>不会把未揭示正文暴露给下一次请求</small></span><select v-model="snapshot.settings.dm.pendingVisibility" class="row-select"><option value="hidden">完全隐藏</option><option value="placeholder">显示状态占位</option></select></label>
        <label class="setting-row"><span><b>气泡数量</b><small>自然模式由模型决定</small></span><select v-model="snapshot.settings.dm.maxBubbleMode" class="row-select"><option value="natural">自然</option><option value="limit">限制上限</option></select></label>
        <label v-if="snapshot.settings.dm.maxBubbleMode==='limit'" class="range-row"><span><b>最多气泡</b><em>{{snapshot.settings.dm.maxBubbles}}</em></span><input v-model.number="snapshot.settings.dm.maxBubbles" type="range" min="1" max="12"></label>
        <label class="switch-row runtime-switch"><span><b>双语消息</b><small>XML 可携带原文与翻译</small></span><input v-model="snapshot.settings.dm.bilingual" type="checkbox"><i></i></label>
        <label class="setting-row"><span><b>人格事实写入</b><small>锁定字段永远不会被模型覆盖</small></span><select v-model="snapshot.settings.dm.factPersistence" class="row-select"><option value="auto">自动写入未锁字段</option><option value="confirm">仅提示待确认</option><option value="conversation-only">仅本对话使用</option></select></label>
        <div class="section-head"><div><b>上下文开关</b><small>只注入当前 NPC 合理可知的论坛资料</small></div></div>
        <label v-for="item in [{k:'publicPosts',t:'公开帖子'},{k:'publicComments',t:'公开评论'},{k:'circles',t:'共同圈子'},{k:'interactions',t:'双方互动'},{k:'forumMemories',t:'论坛记忆'},{k:'chatSummaries',t:'聊天摘要'}]" :key="item.k" class="switch-row runtime-switch"><span>{{item.t}}</span><input v-model="(snapshot.settings.dm.context as any)[item.k]" type="checkbox"><i></i></label>
      </template>

      <template v-else-if="section==='avatars'">
        <div class="section-head"><div><b>NPC 头像库</b><small>本地文件写入 IndexedDB，不受 localStorage 约 5MB 限制</small></div></div>
        <label class="switch-row runtime-switch"><span><b>生成时使用头像库</b><small>优先按性别和占用状态匹配</small></span><input v-model="snapshot.settings.avatarLibraryEnabled" type="checkbox"><i></i></label>
        <label class="switch-row runtime-switch"><span><b>允许极低概率复用</b><small>关闭时活跃 NPC 之间绝不共用头像</small></span><input v-model="snapshot.settings.allowAvatarReuse" type="checkbox"><i></i></label>
        <label v-if="snapshot.settings.allowAvatarReuse" class="range-row"><span><b>复用概率</b><em>{{Math.round(snapshot.settings.avatarReuseProbability*100)}}%</em></span><input v-model.number="snapshot.settings.avatarReuseProbability" type="range" min="0" max="0.05" step="0.001"></label>
        <div class="avatar-tools"><select v-model="avatarGroup"><option value="female">女</option><option value="male">男</option><option value="other">其他/通用</option></select><button @click="avatarFiles?.click()">批量上传</button><input ref="avatarFiles" hidden type="file" accept="image/*" multiple @change="submitAvatarFiles"></div>
        <div class="avatar-tools"><input v-model="avatarUrl" placeholder="https:// 图片地址"><button @click="submitAvatarUrl">添加 URL</button></div>
        <div class="avatar-tools"><input v-model="avatarPrompt" placeholder="AI 头像描述"><button @click="emit('generate-avatar',avatarPrompt,avatarGroup)">AI 生成</button></div>
        <div class="avatar-grid"><article v-for="item in snapshot.avatarLibrary" :key="item.id"><img :src="item.url"><small>{{item.label||item.group}} · {{item.assignedAccountIds.length?'使用中':'未使用'}}</small><button @click="emit('remove-avatar',item.id,false)">移出库</button><button v-if="!item.assignedAccountIds.some(id=>snapshot.accounts.some(a=>a.id===id&&!a.isArchived))&&item.storageKey" @click="emit('remove-avatar',item.id,true)">删文件</button></article></div>
        <p v-if="!snapshot.avatarLibrary.length" class="empty-compact">头像库为空，可批量上传、粘贴 URL 或 AI 生成。</p>
      </template>

      <template v-else>
        <div class="section-head"><div><b>论坛媒体</b><small>媒体文件保存在 IndexedDB，不写入 localStorage</small></div></div>
        <label class="setting-row"><span><b>自动配图</b><small>使用图像大厅中的同一引擎、模型与 API 配置</small></span><select v-model="snapshot.settings.autoImageProvider" class="row-select"><option value="off">关闭</option><option v-for="provider in autoImageProviders" :key="provider.id" :value="provider.id">{{autoImageProviderLabel(provider.id,provider.name)}}</option></select></label><p v-if="snapshot.settings.autoImageProvider==='aihorde'" class="plain-note">AI Horde 使用社区免费志愿算力，可能排队，且 Worker 理论上可以看到提示词和结果；请勿用于真人隐私或敏感内容。</p><div class="setting-row static"><span><b>语音</b><small>复用已配置的 Seed Audio TTS</small></span><i>复用</i></div><div class="setting-row static"><span><b>轻短视频</b><small>图片 + TTS + 字幕 + 前端动画实时播放</small></span><i>实时</i></div>
      </template>
    </div>
    <AvatarUploadModal v-model:visible="avatarUploadVisible" :current-avatar="profileAvatar" shape="circle" title="更换论坛头像" enable-crop @saved="value=>profileAvatar=value||''"/>
  </div>
</template>

